fn place(arr: Vec<f32>, mask: Vec<bool>, vals: Vec<f32>) -> Vec<f32> {
    // The input mask must have the same length as `arr`.
    assert_eq!(arr.len(), mask.len(), "arr and mask must be the same length");
    // `vals` must be non-empty so that we can cycle through it.
    assert!(!vals.is_empty(), "vals must be non-empty");

    let n = arr.len();
    let m = vals.len();
    let mut result = Vec::with_capacity(n);
    let mut replacement_idx = 0;

    for i in 0..n {
        if mask[i] {
            // Place the next replacement value (cyclically).
            result.push(vals[replacement_idx]);
            replacement_idx += 1;
            if replacement_idx == m {
                replacement_idx = 0;
            }
        } else {
            // Preserve the original element.
            result.push(arr[i]);
        }
    }

    result
}

