        let vals = vec![1.0, 2.0];
        // replacements sequence = [1.0, 2.0, 1.0] (cycled)
        let expected = vec![1.0, 20.0, 2.0, 1.0, 50.0];
        assert_eq!(place(arr, mask, vals), expected);
